#![no_std]

//! Handshake bodies for the footprint demos. Each `run_*_facade()` drives
//! `DefaultStream::connect` end-to-end against the seed-0 canned fixtures
//! generated by `tls_fixture/regen.py` — same surface a real caller would
//! use. The `baseline_*` variants `black_box` the fixture rodata without
//! crypto so the `.text` delta isolates the krabitls + AEAD + sig-verify
//! cost.

// Static placement for `DefaultScratch` (≈37 KiB). Sized for arbitrary
// RSA chains; placing it on the stack would blow a small MCU's SRAM
// alongside the crypto stack frame and corrupt `.bss`, which manifests as
// an infinite loop under QEMU. Borrow via `with_scratch` under a
// critical section so concurrent facade calls can't share an aliased
// reference even if a future caller adds threads.
#[cfg(feature = "canned-replay")]
mod facade_scratch {
    use core::cell::RefCell;
    use critical_section::Mutex;
    use krabitls::client::DefaultScratch;

    static SCRATCH: Mutex<RefCell<DefaultScratch>> =
        Mutex::new(RefCell::new(DefaultScratch::new()));

    pub fn with<R>(f: impl FnOnce(&mut DefaultScratch) -> R) -> R {
        critical_section::with(|cs| {
            let mut s = SCRATCH.borrow(cs).borrow_mut();
            f(&mut s)
        })
    }
}

// `concat_sh_sf!(SH_LEN, SF_LEN)` expands to a const block that
// concatenates `SERVER_HELLO || SERVER_FLIGHT` at compile time. Done as
// a macro because the generic-const form (`fn f<const A, const B>() ->
// [u8; A + B]`) is gated on the `generic_const_exprs` nightly feature.
#[cfg(feature = "canned-replay")]
macro_rules! concat_sh_sf {
    ($sh_len:expr, $sf_len:expr) => {{
        let mut out = [0u8; $sh_len + $sf_len];
        let mut i = 0;
        while i < $sh_len {
            out[i] = SERVER_HELLO[i];
            i += 1;
        }
        let mut j = 0;
        while j < $sf_len {
            out[$sh_len + j] = SERVER_FLIGHT[j];
            j += 1;
        }
        out
    }};
}

// Each facade is gated to the exact feature combination its canned bytes
// were generated under. The seed-0 ClientHello changes shape under
// `rsa` (extra sig scheme) and `chacha20` (cipher list), so a build that
// enables one of those alongside the wrong fixture would deterministically
// return `Err(())` even though nothing is actually broken — the wire bytes
// just no longer match what the facade now emits.

#[cfg(all(
    feature = "canned-replay",
    feature = "cipher-aes",
    not(feature = "chacha20"),
    not(feature = "rsa"),
    not(feature = "mlkem"),
    not(feature = "mldsa"),
))]
mod fixture_aes_ed25519_facade {
    pub const CLIENT_HELLO: [u8; 149] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets/001_c2s_ClientHello.hex"
    ));
    pub const SERVER_HELLO: [u8; 95] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets/002_s2c_ServerHello.hex"
    ));
    pub const SERVER_FLIGHT: [u8; 415] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets/003_s2c_ServerFlight_encrypted.hex"
    ));
    pub const CLIENT_FINISHED: [u8; 58] = krabitls::hex_decode(include_str!(
        "../../../testdata/packets/004_c2s_ClientFinished_encrypted.hex"
    ));
    pub const SERVER_STREAM: [u8; SERVER_HELLO.len() + SERVER_FLIGHT.len()] =
        concat_sh_sf!(SERVER_HELLO.len(), SERVER_FLIGHT.len());
}

